import { Component, OnInit } from '@angular/core';
import { ApplicationService } from '../../../core/services/application.service';
import { AuthService } from '../../../core/services/auth.service';
import { Application, ApplicationStatus } from '../../../core/models/application.model';

@Component({
  selector: 'app-my-applications',
  templateUrl: './my-applications.component.html',
  styleUrls: ['./my-applications.component.css']
})
export class MyApplicationsComponent implements OnInit {
  applications: Application[] = [];
  isLoading = true;
  hasError = false;

  constructor(
    private applicationService: ApplicationService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    this.fetchApplications();
  }

  fetchApplications(): void {
    const userId = this.authService.getUserId();
    if (!userId) {
      this.isLoading = false;
      return;
    }

    this.isLoading = true;
    this.hasError = false;

    this.applicationService.getMyApplications(userId).subscribe({
      next: (res) => {
        this.applications = res.data || [];
        this.isLoading = false;
      },
      error: () => {
        this.hasError = true;
        this.isLoading = false;
      }
    });
  }

  getStatusBadgeClass(status: ApplicationStatus | string): string {
    switch (status) {
      case 'accepted':
      case 'hired':
        return 'badge-success';
      case 'rejected':
        return 'badge-danger';
      case 'pending':
      default:
        return 'badge-warning';
    }
  }

  getJobId(job: any): string | null {
    if (!job) return null;
    return typeof job === 'object' ? (job._id || job.id) : job;
  }
}
<div class="my-applications-page container section-padding">
  <div class="page-header mb-4">
    <h1 class="page-title">My Job Applications</h1>
    <p class="page-subtitle">Track the status of your submitted applications and interview progress in real-time.</p>
  </div>

  <!-- Loading State -->
  <app-loading-spinner *ngIf="isLoading" message="Fetching your applications..."></app-loading-spinner>

  <!-- Error Alert -->
  <div class="alert alert-danger" *ngIf="hasError && !isLoading">
    <i class="fa-solid fa-circle-exclamation"></i>
    <div>Failed to load applications. <button class="btn btn-sm btn-outline-danger" (click)="fetchApplications()">Retry</button></div>
  </div>

  <!-- Empty State -->
  <app-empty-state
    *ngIf="!isLoading && !hasError && applications.length === 0"
    icon="fa-regular fa-file-lines"
    title="No Applications Submitted"
    message="You have not applied to any job openings yet. Start browsing open positions today."
    actionText="Browse Available Jobs"
    actionRoute="/jobs">
  </app-empty-state>

  <!-- Applications List -->
  <div class="applications-grid" *ngIf="!isLoading && !hasError && applications.length > 0">
    <div class="card app-item-card" *ngFor="let app of applications">
      <div class="app-card-header d-flex justify-content-between align-items-start gap-2">
        <div>
          <h3 class="app-job-title">{{ app.jobTitle }}</h3>
          <span class="app-applicant-name">Applicant: {{ app.applicantName }}</span>
        </div>
        <div class="app-badges d-flex align-items-center gap-2">
          <span *ngIf="app.matchScore !== undefined" class="match-score-pill" [ngClass]="{
            'match-high': app.matchScore >= 70,
            'match-medium': app.matchScore >= 40 && app.matchScore < 70,
            'match-low': app.matchScore < 40
          }">
            <i class="fa-solid fa-bolt"></i> {{ app.matchScore }}% Match
          </span>
          <span class="badge" [ngClass]="getStatusBadgeClass(app.status)">
            {{ app.status }}
          </span>
        </div>
      </div>

      <div class="app-card-body">
        <div class="cv-info-row">
          <span class="text-muted"><i class="fa-solid fa-link"></i> CV Reference:</span>
          <a [href]="app.cv" target="_blank" rel="noopener noreferrer" class="cv-link font-medium" *ngIf="app.cv.startsWith('http')">
            {{ app.cv | slice:0:45 }}{{ app.cv.length > 45 ? '...' : '' }}
          </a>
          <span class="cv-text font-medium" *ngIf="!app.cv.startsWith('http')">
            {{ app.cv }}
          </span>
        </div>
      </div>

      <div class="app-card-footer d-flex justify-content-between align-items-center">
        <span class="app-date text-muted text-sm" *ngIf="app.createdAt">
          Submitted {{ app.createdAt | date:'mediumDate' }}
        </span>
        <a
          *ngIf="getJobId(app.jobId)"
          [routerLink]="['/jobs', getJobId(app.jobId)]"
          class="btn btn-outline btn-sm">
          View Job Details <i class="fa-solid fa-arrow-right"></i>
        </a>
      </div>
    </div>
  </div>
</div>
